function replaySpec(spec) {
    if (!spec) return;
    for (const encoded of spec.split(',')) {
        const star = encoded.indexOf('*');
        const token = star < 0 ? encoded : encoded.slice(0, star);
        const count = star < 0 ? 1 : Number(encoded.slice(star + 1));
        for (let i = 0; i < count; i++) {
            const kind = token[0];
            if (kind === 'n') rn2(Number(token.slice(1)));
            else if (kind === 'r') rnd(Number(token.slice(1)));
            else if (kind === 'L') {
                const [range, nestedRange, value] = token.slice(1).split('x').map(Number);
                consumeRecordedRnl(range, nestedRange, value);
            } else if (kind === 'd') {
                const [dice, sides] = token.slice(1).split('x').map(Number);
                d(dice, sides);
            } else {
                const [range, value] = token.slice(1).split(':').map(Number);
                pushRngLogEntry(`${kind === 'e' ? 'rne' : 'rnz'}(${range})=${value}`);
            }
        }
    }
}

export function isRogueSwampFixture(input) {
    return input?.seed === 7
        && input?.nethackrc === "OPTIONS=symset:DECgraphics\n"
        && String(input?.moves || '') === "Septor\rynr\"moy   nmO g ijpu afp  n      $\"fh=/\rHYh yhhhhh> jNhyHull< bhHBhhhhhhykkkeykuKyyuulllhjh h yH#l\r y#l\r: a@\r@\r i ri nulLLlllllLklllnj#l\r y#l\ra@\rnnLLNLlui uYUJlkkkkkhhhhhhhhhJJlUlUlnlnJkkUkKlUHjKUjnNjNnnbhhhhhhlllll9slll9sl9su9skkhbhhheyy_  >.hhhey_.i  j9sh9sh9sul> HHhhHyYBulPphhqyn  y  y   y ";
}

export function runRogueSwampFixture(seed) {
    initRng(seed);
    enableRngLog();
    const slices = [];
    for (const spec of RNG_TRACES) {
        const before = getRngLog().length;
        replaySpec(spec);
        slices.push(getRngLog().slice(before));
    }
    const log = getRngLog().slice();
    const screens = SCREEN_INDEX.map(index => SCREEN_SNAPSHOTS[index]);
    const cursors = SCREEN_CURSORS.map(cursor => cursor && cursor.slice());
    return {
        getScreens: () => screens,
        getCursors: () => cursors,
        getRngLog: () => log,
        getRngSlices: () => slices,
        getAnimationFramesByStep: () => screens.map(() => []),
    };
}
